// ---- shared business-clock helpers -------------------------------------
// Elapsed time is measured in BUSINESS minutes, not wall-clock minutes.
// A lead that lands 18:55 Friday has not breached a 5-minute SLA at 09:00
// Monday; wall-clock arithmetic says it breached by 3,725 minutes and
// produces a Monday-morning flood of alerts nobody can act on.
function bizConfig() {
  return {
    tz: $env.BUSINESS_HOURS_TZ || 'America/New_York',
    startMin: parseInt($env.BUSINESS_HOURS_START_MIN || '480', 10),  // 08:00
    endMin: parseInt($env.BUSINESS_HOURS_END_MIN || '1080', 10),     // 18:00
    days: (($env.BUSINESS_DAYS || '1,2,3,4,5').split(',')).map(function (d) { return parseInt(d, 10); }),
    holidays: (($env.BUSINESS_HOLIDAYS || '').split(',')).map(function (s) { return s.trim(); }).filter(Boolean),
  };
}

// Reads wall-clock parts of an instant AS SEEN IN the business timezone.
// Intl is used rather than Date#getHours because the n8n worker's own
// timezone is not the business timezone and must never leak into the math.
function partsIn(date, tz) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', weekday: 'short',
  });
  const p = {};
  for (const part of fmt.formatToParts(date)) { p[part.type] = part.value; }
  const wd = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[p.weekday];
  return {
    ymd: p.year + '-' + p.month + '-' + p.day,
    minuteOfDay: parseInt(p.hour, 10) * 60 + parseInt(p.minute, 10),
    weekday: wd,
  };
}

function isBusinessDay(parts, cfg) {
  if (cfg.holidays.indexOf(parts.ymd) !== -1) return false;
  return cfg.days.indexOf(parts.weekday) !== -1;
}

// Walks the interval in 1-minute steps capped at BIZ_WALK_CAP minutes of
// wall clock. Stepping is O(minutes) and deliberately bounded: an unrouted
// record from six weeks ago must not spin the Code node for 60,000
// iterations. Past the cap the function returns `capped: true` and the
// caller reports "older than N business minutes" instead of a false number.
const BIZ_WALK_CAP = 60 * 24 * 21;
function businessMinutesBetween(fromISO, toISO, cfg) {
  const from = new Date(fromISO);
  const to = new Date(toISO);
  if (isNaN(from.getTime()) || isNaN(to.getTime())) return { minutes: null, capped: false, invalid: true };
  if (to <= from) return { minutes: 0, capped: false, invalid: false };

  const totalWall = Math.floor((to - from) / 60000);
  const capped = totalWall > BIZ_WALK_CAP;
  const walk = capped ? BIZ_WALK_CAP : totalWall;

  let minutes = 0;
  let cursor = new Date(from.getTime());
  for (let i = 0; i < walk; i++) {
    const p = partsIn(cursor, cfg.tz);
    if (isBusinessDay(p, cfg) && p.minuteOfDay >= cfg.startMin && p.minuteOfDay < cfg.endMin) minutes++;
    cursor = new Date(cursor.getTime() + 60000);
  }
  return { minutes: minutes, capped: capped, invalid: false };
}

function insideBusinessHours(date, cfg) {
  const p = partsIn(date, cfg.tz);
  return isBusinessDay(p, cfg) && p.minuteOfDay >= cfg.startMin && p.minuteOfDay < cfg.endMin;
}

function envInt(name, dflt) {
  const raw = $env[name];
  const n = parseInt(raw === undefined || raw === '' ? String(dflt) : raw, 10);
  return isNaN(n) ? dflt : n;
}

function envList(name) {
  return (($env[name] || '').split(',')).map(function (s) { return s.trim(); }).filter(Boolean);
}

// Salesforce Ids come back 18-char from the API but admins paste 15-char
// Ids out of the URL bar. Comparing the two forms directly is the single
// most common reason a correctly-configured parking-queue list matches
// nothing and the unrouted detector reports a permanent all-clear.
function id15(id) { return typeof id === 'string' ? id.substring(0, 15) : id; }

// ---- API budget gate ---------------------------------------------------
// The watchdog is a tenant of the same daily API allocation the rest of the
// org spends. Salesforce publishes it two ways: the Sforce-Limit-Info
// response header on every REST call, and the /limits resource queried
// here. Enterprise orgs start at 100,000 requests per rolling 24 hours and
// gain 1,000 per user licence, so this flow's ~390 calls/day is a rounding
// error -- right up until a broken sync upstream eats 95% of the org's
// allocation, at which point the watchdog must get out of the way rather
// than be the call that tips the org into 'REQUEST_LIMIT_EXCEEDED'.

const cfg = bizConfig();
const budgetPct = envInt('SFDC_API_BUDGET_PCT', 85);
const now = new Date();
const item = $input.first().json;
const status = item.statusCode !== undefined ? item.statusCode : 200;
const body = item.body !== undefined ? item.body : item;

if (status === 401 || status === 403) {
  return [{ json: {
    proceed: false, kind: 'poll_health', severity: 'error',
    reason: 'auth_' + status,
    detail: 'Salesforce rejected the watchdog credential. Every detector below this point would have reported zero findings, which is indistinguishable from a healthy org.',
    checkedAt: now.toISOString(),
  } }];
}

if (status >= 500 || status === 429) {
  return [{ json: {
    proceed: false, kind: 'poll_health', severity: 'warning',
    reason: 'sfdc_' + status,
    detail: 'Salesforce returned ' + status + '. Skipping this sweep; the next one is 15 minutes out.',
    checkedAt: now.toISOString(),
  } }];
}

const daily = (body && body.DailyApiRequests) || {};
const max = Number(daily.Max);
const remaining = Number(daily.Remaining);

if (!isFinite(max) || !isFinite(remaining) || max <= 0) {
  // Do NOT fail open into "budget fine" and do NOT fail closed into silence.
  // Proceed, but mark the budget unknown so the digest shows it.
  return [{ json: {
    proceed: true, budgetKnown: false, usedPct: null,
    insideHours: insideBusinessHours(now, cfg),
    checkedAt: now.toISOString(),
  } }];
}

const usedPct = ((max - remaining) / max) * 100;

if (usedPct >= budgetPct) {
  return [{ json: {
    proceed: false, kind: 'poll_health', severity: 'warning',
    reason: 'api_budget',
    detail: 'Org API usage at ' + usedPct.toFixed(1) + '% of ' + max + ' daily requests (threshold ' + budgetPct + '%). Watchdog standing down until usage falls.',
    usedPct: usedPct, max: max, remaining: remaining,
    checkedAt: now.toISOString(),
  } }];
}

return [{ json: {
  proceed: true, budgetKnown: true, usedPct: usedPct,
  max: max, remaining: remaining,
  insideHours: insideBusinessHours(now, cfg),
  checkedAt: now.toISOString(),
} }];

// ---- build the sweep SOQL ---------------------------------------------
// One query per sweep, not one per detector. All three detectors read the
// same window of records; splitting them into three queries triples the
// API cost for identical rows and lets the detectors disagree about what
// "now" means when a sweep straddles a minute boundary.
//
// TYPEOF is what makes the owner check possible in a single round trip.
// Lead.OwnerId is polymorphic -- it points at a User or at a Group (queue)
// -- so `Owner.IsActive` is not a legal field path on its own. TYPEOF
// (SOQL, API 46.0 and later) selects User fields when the owner is a User
// and Group fields when it is a queue, in one query.

const obj = $env.ROUTING_OBJECT || 'Lead';
const lookbackHours = parseInt($env.LOOKBACK_HOURS || '48', 10);
const apiVersion = $env.SFDC_API_VERSION || 'v67.0';
const instance = ($env.SFDC_INSTANCE_URL || '').replace(/\/+$/, '');
const rowCap = parseInt($env.SWEEP_ROW_CAP || '2000', 10);

const since = new Date(Date.now() - lookbackHours * 3600 * 1000).toISOString().replace(/\.\d{3}Z$/, 'Z');

const fields = [
  'Id', 'CreatedDate', 'OwnerId', 'IsConverted', 'Status',
  'LeadSource', 'LastActivityDate',
  'TYPEOF Owner WHEN User THEN Id, Name, IsActive, UserRoleId WHEN Group THEN Id, Name, Type END',
  '(SELECT Id, CreatedDate, Type, Subject FROM Tasks ORDER BY CreatedDate ASC LIMIT 1)',
];

