if (routingTsField) fields.splice(6, 0, routingTsField);

const soql =
  'SELECT ' + fields.join(', ') +
  ' FROM ' + obj +
  ' WHERE CreatedDate >= ' + since +
  ' AND IsConverted = false' +
  ' ORDER BY CreatedDate DESC' +
  ' LIMIT ' + rowCap;

return [{ json: {
  url: instance + '/services/data/' + apiVersion + '/query/?q=' + encodeURIComponent(soql),
  soql: soql,
  object: obj,
  since: since,
  rowCap: rowCap,
  routingTsField: routingTsField,
  budget: $input.first().json,
} }];

