const nowISO = new Date().toISOString();
const meta = $('Build Sweep Query').first().json;
const parking = new Set(envList('PARKING_OWNER_IDS').map(id15));
const routingTsField = meta.routingTsField;

const raw = $input.first().json;
const status = raw.statusCode !== undefined ? raw.statusCode : 200;
