  //      CreatedDate, which would silently report routing latency of 0
  //      for every record in the org.
  let routedAt = null, routedAtSource = 'none';
  if (routingTsField && r[routingTsField]) { routedAt = r[routingTsField]; routedAtSource = 'field:' + routingTsField; }

  const firstTask = (r.Tasks && r.Tasks.records && r.Tasks.records[0]) || null;
  const firstTouchAt = firstTask ? firstTask.CreatedDate : (r.LastActivityDate ? r.LastActivityDate + 'T00:00:00Z' : null);
  const firstTouchSource = firstTask ? 'task' : (r.LastActivityDate ? 'lastActivityDate' : 'none');

  const ageBiz = businessMinutesBetween(r.CreatedDate, nowISO, cfg);
  const routeClock = routedAt ? businessMinutesBetween(r.CreatedDate, routedAt, cfg) : { minutes: null, capped: false };
  const responseClock = (routedAt && firstTouchAt)
    ? businessMinutesBetween(routedAt, firstTouchAt, cfg)
    : (routedAt ? businessMinutesBetween(routedAt, nowISO, cfg) : { minutes: null, capped: false });

  if (isParked) parked++; else if (ownerInactive) inactiveOwner++; else assigned++;

  out.push({ json: {
    kind: 'record',
    id: r.Id,
    createdAt: r.CreatedDate,
    leadSource: r.LeadSource || null,
    status: r.Status || null,
    ownerId: r.OwnerId,
    ownerName: owner.Name || null,
    ownerIsQueue: ownerIsQueue,
    ownerInactive: ownerInactive,
    isParked: isParked,
    routedAt: routedAt,
    routedAtSource: routedAtSource,
    firstTouchAt: firstTouchAt,
    firstTouchSource: firstTouchSource,
    ageBizMinutes: ageBiz.minutes,
    ageCapped: ageBiz.capped,
    routeBizMinutes: routeClock.minutes,
