  for (const rec of (body.records || [])) {
    const rid = rec[recordIdField];
    if (!rid) continue;
    const prev = logs[rid];
    if (!prev || new Date(rec.CreatedDate) < new Date(prev.CreatedDate)) logs[rid] = rec;
