const passthrough = items.filter(function (j) { return j.kind === 'poll_health'; });

const graceMin = envInt('UNROUTED_GRACE_MINUTES', 10);
const backlogWarn = envInt('UNROUTED_BACKLOG_WARN', 25);
const backlogPage = envInt('UNROUTED_BACKLOG_PAGE', 100);
const routingSla = envInt('ROUTING_SLA_MINUTES', 2);
const responseSla = envInt('RESPONSE_SLA_MINUTES', 5);
const stampedeMin = envInt('STAMPEDE_MIN_BATCH', 250);
const maxSample = envInt('MAX_ITEMS_PER_ALERT', 25);

const findings = [];
const sample = function (arr) { return arr.slice(0, maxSample).map(function (r) { return { id: r.id, owner: r.ownerName, ageBizMinutes: r.ageBizMinutes, createdAt: r.createdAt }; }); };

// ---------------------------------------------------------------- guard 1
// Zero rows during business hours is a broken watchdog until proven
// otherwise. This finding fires INSTEAD of any all-clear.
if (summary.sampled === 0) {
  if (summary.insideHours) {
    findings.push({
      kind: 'finding', class: 'poll_health', severity: 'error', channel: 'page',
      dedupKey: 'watchdog::no_denominator',
      count: 0, sample: [],
      detail: 'Sweep returned zero records during business hours over a ' + (envInt('LOOKBACK_HOURS', 48)) + 'h window. Either inbound has stopped or the query/filter is broken. No detector can distinguish those, so none of them ran.',
    });
  }
  return findings.concat(passthrough).map(function (j) { return { json: j }; });
}

if (summary.truncated) {
  findings.push({
    kind: 'finding', class: 'poll_health', severity: 'warning', channel: 'post',
    dedupKey: 'watchdog::truncated_sweep',
    count: summary.totalSize, sample: [],
    detail: 'Sweep hit the ' + envInt('SWEEP_ROW_CAP', 2000) + '-row cap against ' + summary.totalSize + ' matching records. Counts below are floors, not totals. Shorten LOOKBACK_HOURS or raise SWEEP_ROW_CAP.',
  });
}

// ---------------------------------------------------- detector 1: unrouted
// Lead.OwnerId is NEVER null. When no assignment rule matches, Salesforce
// assigns the record to the Default Lead Owner configured in Lead Settings.
// So "unrouted" is not a null test -- it is membership in a configured set
// of parking owners (the default owner plus any unsorted/holding queues).
// An empty PARKING_OWNER_IDS means this detector cannot work, and says so
// rather than reporting a permanent all-clear.
const parkingConfigured = envList('PARKING_OWNER_IDS').length > 0;
if (!parkingConfigured) {
  findings.push({
    kind: 'finding', class: 'config', severity: 'warning', channel: 'post',
    dedupKey: 'watchdog::parking_unconfigured',
    count: 0, sample: [],
    detail: 'PARKING_OWNER_IDS is empty, so the unrouted detector is disabled. Set it to your Default Lead Owner plus every holding queue, or this watchdog will never report an unrouted lead.',
  });
} else {
  const stuck = records.filter(function (r) { return r.isParked && r.ageBizMinutes !== null && r.ageBizMinutes >= graceMin; });

  // Stampede suppression. A marketing list import legitimately parks tens
  // of thousands of records for minutes. Alerting on the absolute count
  // turns every import into an incident; alerting on nothing misses the
  // real backlog. The discriminator is source concentration: a genuine
  // routing failure is spread across LeadSource values, an import is not.
  const bySource = {};
  for (const r of stuck) { const k = r.leadSource || '(none)'; bySource[k] = (bySource[k] || 0) + 1; }
  const sources = Object.keys(bySource);
  const topSource = sources.sort(function (a, b) { return bySource[b] - bySource[a]; })[0];
  const topShare = topSource ? bySource[topSource] / stuck.length : 0;
  const stampede = stuck.length >= stampedeMin && topShare >= 0.9 && sources.length > 0;

  if (stuck.length > 0 && !stampede) {
    const sev = stuck.length >= backlogPage ? 'critical' : (stuck.length >= backlogWarn ? 'error' : 'warning');
    findings.push({
      kind: 'finding', class: 'unrouted_backlog',
      severity: sev,
      channel: sev === 'critical' ? 'page' : 'post',
      dedupKey: 'watchdog::unrouted_backlog',
      count: stuck.length, sample: sample(stuck),
      detail: stuck.length + ' record(s) still owned by a parking queue past the ' + graceMin + '-business-minute grace window. Oldest: ' + Math.max.apply(null, stuck.map(function (r) { return r.ageBizMinutes || 0; })) + ' business minutes.',
    });
  } else if (stampede) {
    findings.push({
      kind: 'finding', class: 'unrouted_stampede', severity: 'info', channel: 'post',
      dedupKey: 'watchdog::unrouted_stampede',
      count: stuck.length, sample: sample(stuck),
      detail: stuck.length + ' parked records, ' + Math.round(topShare * 100) + '% from LeadSource "' + topSource + '". Reads as a bulk import rather than a routing failure; paging suppressed. Re-check after ' + envInt('STAMPEDE_SUPPRESS_MINUTES', 30) + ' minutes.',
    });
  }
}

// ------------------------------------------ detector 2: assignment defects
// An owner who has left the company is the one mis-assignment class that
// is deterministic from CRM data alone. It is also the most expensive:
// the record looks routed on every dashboard, so nothing else ever flags
// it, and it sits in a deactivated user's name until someone audits.
const orphaned = records.filter(function (r) { return r.ownerInactive; });
if (orphaned.length > 0) {
  const byOwner = {};
  for (const r of orphaned) { const k = r.ownerName || r.ownerId; byOwner[k] = (byOwner[k] || 0) + 1; }
  findings.push({
    kind: 'finding', class: 'inactive_owner',
    severity: orphaned.length >= backlogWarn ? 'error' : 'warning',
    channel: orphaned.length >= backlogWarn ? 'page' : 'post',
    dedupKey: 'watchdog::inactive_owner',
    count: orphaned.length, sample: sample(orphaned),
    detail: orphaned.length + ' record(s) assigned to a deactivated user. Owners: ' + Object.keys(byOwner).map(function (k) { return k + ' (' + byOwner[k] + ')'; }).join(', ') + '. These read as routed everywhere except here.',
  });
}

// ------------------------------------------------ detector 3: the two clocks
// Split deliberately. Routing latency is the router's fault and pages.
// Response latency is a rep/manager conversation and never pages.
const routable = records.filter(function (r) { return r.routeBizMinutes !== null; });
const routingBreaches = routable.filter(function (r) { return r.routeBizMinutes > routingSla; });
const noRoutingClock = records.filter(function (r) { return r.routedAtSource === 'none' && !r.isParked; });

if (routingBreaches.length > 0) {
  const worst = Math.max.apply(null, routingBreaches.map(function (r) { return r.routeBizMinutes; }));
  findings.push({
    kind: 'finding', class: 'routing_latency',
    severity: worst >= routingSla * 10 ? 'critical' : 'error',
    channel: 'page',
    dedupKey: 'watchdog::routing_latency',
    count: routingBreaches.length, sample: sample(routingBreaches),
    detail: routingBreaches.length + ' of ' + routable.length + ' records took longer than ' + routingSla + ' business minutes to get an owner (worst: ' + worst + '). This is the router, not the rep.',
  });
}

if (noRoutingClock.length > 0 && noRoutingClock.length === records.length) {
  findings.push({
    kind: 'finding', class: 'config', severity: 'warning', channel: 'post',
    dedupKey: 'watchdog::no_routing_clock',
    count: noRoutingClock.length, sample: [],
    detail: 'No record in this sweep has a routing timestamp. Set ROUTING_TS_FIELD to a routed-at field on the object, or enable LEANDATA_LOG_ENABLED. Until then the routing-latency detector is dark and only the response clock runs.',
  });
}

const responseBreaches = records.filter(function (r) {
  return r.responseOpen && r.responseBizMinutes !== null && r.responseBizMinutes > responseSla && !r.isParked && !r.ownerInactive;
});
if (responseBreaches.length > 0) {
  const byOwner = {};
  for (const r of responseBreaches) { const k = r.ownerName || r.ownerId; byOwner[k] = (byOwner[k] || 0) + 1; }
  findings.push({
    kind: 'finding', class: 'response_latency', severity: 'warning', channel: 'post',
    dedupKey: 'watchdog::response_latency',
    count: responseBreaches.length, sample: sample(responseBreaches),
    detail: responseBreaches.length + ' assigned record(s) past the ' + responseSla + '-business-minute first-touch SLA with no logged activity. Top owners: ' + Object.keys(byOwner).sort(function (a, b) { return byOwner[b] - byOwner[a]; }).slice(0, 5).map(function (k) { return k + ' (' + byOwner[k] + ')'; }).join(', ') + '. Coaching signal, not an incident -- never paged.',
  });
}

// An explicit all-clear item. The gate needs it to send resolve events for
// classes that fired on a previous sweep and no longer match.
findings.push({
  kind: 'sweep_result',
  classesFiring: findings.map(function (f) { return f.dedupKey; }),
  sampled: summary.sampled, parked: summary.parked,
  assigned: summary.assigned, inactiveOwner: summary.inactiveOwner,
  insideHours: summary.insideHours,
  checkedAt: nowISO,
});

return findings.concat(passthrough).map(function (j) { return { json: j }; });

// ---- alert gate: dedup, resolve, and route to a channel ----------------
// Three jobs, in this order.
//
// 1. DEDUP. A 15-minute poll against a condition that persists for a day
//    is 96 identical alerts. Findings are keyed on dedupKey and suppressed
//    for RENOTIFY_MINUTES unless the severity escalates.
// 2. RESOLVE. A dedupKey that fired on a previous sweep and is absent from
//    this one emits an explicit resolve. Without it, PagerDuty incidents
//    stay open after the condition clears and the next real page arrives
//    in a channel everyone has learned to ignore.
// 3. ROUTE. `channel: 'page'` goes to PagerDuty; everything else goes to
//    Slack. The policy: page only for what the on-call can fix right now.
//
// State lives in workflow static data, which n8n persists on PRODUCTION
// executions only. Testing this node with the manual run button will show
// no deduplication at all -- that is the documented behaviour, not a bug,
// and the verification step in _README.md uses an activated schedule.

const staticData = $getWorkflowStaticData('global');
staticData.fired = staticData.fired || {};

const renotifyMin = parseInt($env.RENOTIFY_MINUTES || '120', 10);
const now = Date.now();
const nowISO = new Date().toISOString();
const sevRank = { info: 0, warning: 1, error: 2, critical: 3 };

const items = $input.all().map(function (i) { return i.json; });
const findings = items.filter(function (j) { return j.kind === 'finding'; });
const health = items.filter(function (j) { return j.kind === 'poll_health'; });
const result = items.find(function (j) { return j.kind === 'sweep_result'; });

// poll_health items produced upstream (auth failure, budget stand-down)
// are findings for gating purposes -- they are exactly the case where
// every other detector went quiet for the wrong reason.
for (const h of health) {
  findings.push({
    kind: 'finding', class: 'poll_health', severity: h.severity || 'warning',
    channel: (h.severity === 'error' || h.severity === 'critical') ? 'page' : 'post',
    dedupKey: 'watchdog::' + (h.reason || 'poll_health'),
    count: 0, sample: [], detail: h.detail || h.reason,
  });
}

const out = [];
const firingNow = {};

for (const f of findings) {
  firingNow[f.dedupKey] = true;
  const prev = staticData.fired[f.dedupKey];
  const escalated = prev && sevRank[f.severity] > sevRank[prev.severity];
  const aged = prev && (now - prev.at) >= renotifyMin * 60 * 1000;

  if (prev && !escalated && !aged) continue;

  staticData.fired[f.dedupKey] = { at: now, severity: f.severity, channel: f.channel, source: f.source || 'sweep' };
  out.push({ json: Object.assign({}, f, {
    action: 'trigger',
    escalated: !!escalated,
    renotify: !!aged && !escalated,
    emittedAt: nowISO,
  }) });
}

// Resolves. Three conditions, all required.
//   - the key was opened by us
//   - the sweep that would have re-detected it ran successfully (a sweep
//     that died on an auth error must not resolve yesterday's real backlog
//     into silence)
//   - the key belongs to THIS trigger's detector set. The 15-minute sweep
//     and the 08:00 fairness job share this gate and share the state
//     object; without the source scope the sweep would resolve every
//     fairness alert fifteen minutes after it fired, every single day.
const sweepHealthy = !!result && result.sampled > 0;
if (sweepHealthy) {
  for (const key of Object.keys(staticData.fired)) {
    if (firingNow[key]) continue;
    const prev = staticData.fired[key];
    if ((prev.source || 'sweep') !== 'sweep') continue;
    delete staticData.fired[key];
    out.push({ json: {
      kind: 'finding', class: 'resolved', severity: 'info',
      channel: prev.channel, dedupKey: key,
      action: 'resolve', count: 0, sample: [],
      detail: 'Condition cleared: ' + key,
      emittedAt: nowISO,
    } });
  }
}

if (out.length === 0) {
  return [{ json: { kind: 'noop', suppressed: findings.length, checkedAt: nowISO } }];
}

return out;

// ---- PagerDuty Events API v2 payload ----------------------------------
// POST https://events.pagerduty.com/v2/enqueue
// routing_key is the integration key from an Events API v2 integration on
// the target service. dedup_key ties trigger and resolve together: send
// the same key with event_action 'resolve' and PagerDuty closes the alert
// it opened, which is what keeps the on-call's incident list honest.

const j = $json;
const severityMap = { info: 'info', warning: 'warning', error: 'error', critical: 'critical' };

if (j.action === 'resolve') {
  return [{ json: {
    routing_key: $env.PAGERDUTY_ROUTING_KEY,
    event_action: 'resolve',
    dedup_key: j.dedupKey,
  } }];
}

const titles = {
  unrouted_backlog: 'Leads stuck in a parking queue',
  routing_latency: 'Lead routing latency past SLA',
  inactive_owner: 'Leads assigned to a deactivated user',
  poll_health: 'Routing watchdog cannot see Salesforce',
};

return [{ json: {
  routing_key: $env.PAGERDUTY_ROUTING_KEY,
  event_action: 'trigger',
  dedup_key: j.dedupKey,
  payload: {
    summary: (titles[j.class] || j.class) + ' -- ' + j.count + ' record(s)',
    severity: severityMap[j.severity] || 'warning',
    source: ($env.SFDC_INSTANCE_URL || 'salesforce') + '/' + ($env.ROUTING_OBJECT || 'Lead'),
    component: 'lead-routing',
    group: 'revops',
    class: j.class,
    custom_details: {
      detail: j.detail,
      count: j.count,
      sample: j.sample,
      escalated: j.escalated || false,
    },
  },
  links: [{
    href: ($env.SFDC_INSTANCE_URL || '') + '/lightning/o/' + ($env.ROUTING_OBJECT || 'Lead') + '/list',
    text: 'Open the object list view',
  }],
} }];

// ---- Slack Block Kit ---------------------------------------------------
// One message per finding, not one per record. A systemic failure is one
// cause and N symptoms; posting N messages buries the cause and trains the
// channel to mute the bot.

const j = $json;
const icons = { info: ':white_circle:', warning: ':large_yellow_circle:', error: ':red_circle:', critical: ':rotating_light:' };
const instance = ($env.SFDC_INSTANCE_URL || '').replace(/\/+$/, '');

if (j.action === 'resolve') {
  return [{ json: {
    channel: $env.SLACK_CHANNEL_ID,
    text: 'Resolved: ' + j.dedupKey,
    blocks: [{ type: 'section', text: { type: 'mrkdwn', text: ':white_check_mark: *Resolved* -- `' + j.dedupKey + '` no longer matches.' } }],
  } }];
}

const lines = (j.sample || []).slice(0, 10).map(function (s) {
  return '- <' + instance + '/' + s.id + '|' + s.id + '> -- ' + (s.owner || 'unknown owner') + ' -- ' + (s.ageBizMinutes === null ? 'age unknown' : s.ageBizMinutes + ' biz min');
});
const overflow = (j.count || 0) - lines.length;

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: (icons[j.severity] || '') + ' ' + j.class.replace(/_/g, ' ') } },
  { type: 'section', text: { type: 'mrkdwn', text: j.detail } },
];
if (lines.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: lines.join('\n') + (overflow > 0 ? '\n_+ ' + overflow + ' more_' : '') } });
}
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: '`' + j.dedupKey + '` | severity `' + j.severity + '` | ' + j.emittedAt + (j.renotify ? ' | re-notify' : '') + (j.escalated ? ' | escalated' : '') }] });

return [{ json: {
  channel: $env.SLACK_CHANNEL_ID,
  text: j.class + ': ' + j.detail,
  blocks: blocks,
} }];

// ---- build the fairness query -----------------------------------------
// Round-robin skew is invisible on every routing dashboard because each
// individual assignment is valid. The failure is distributional: a rep
// whose calendar broke, whose licence lapsed, or who was removed from a
// pool by a config change stops receiving records, and the pool silently
// redistributes their share to everyone else. Nothing errors. Nothing is
// unrouted. The number only shows up in aggregate.

const obj = $env.ROUTING_OBJECT || 'Lead';
const apiVersion = $env.SFDC_API_VERSION || 'v67.0';
const instance = ($env.SFDC_INSTANCE_URL || '').replace(/\/+$/, '');
const days = parseInt($env.RR_WINDOW_DAYS || '7', 10);
const since = new Date(Date.now() - days * 86400 * 1000).toISOString().replace(/\.\d{3}Z$/, 'Z');

// Aggregate SOQL: the grouping happens in Salesforce, so this returns one
// row per owner rather than one row per lead. That is the difference
// between ~40 rows and ~40,000 for the same answer.
const soql =
  'SELECT OwnerId, COUNT(Id) assignedCount FROM ' + obj +
  ' WHERE CreatedDate >= ' + since +
  ' AND IsConverted = false' +
  ' GROUP BY OwnerId' +
  ' ORDER BY COUNT(Id) DESC';

return [{ json: {
  url: instance + '/services/data/' + apiVersion + '/query/?q=' + encodeURIComponent(soql),
  soql: soql, windowDays: days, since: since,
} }];

// ---- round-robin fairness ---------------------------------------------
// Compares each pool member's share against an equal-share baseline.
// Two thresholds, both required, because either alone produces noise:
//   RR_MIN_ASSIGNMENTS  -- below this the pool is too small for share to
//                          mean anything (3 leads across 4 reps will always
//                          look unfair and never is).
//   RR_MIN_SHARE_RATIO  -- how far below equal share counts as broken.
//                          0.5 means "received less than half of what an
//                          equal split would have given you".
// A member at exactly zero is reported separately: zero is qualitatively
// different from low, and is nearly always a config or licence problem
// rather than a distribution one.

const pool = (($env.RR_POOL_OWNER_IDS || '').split(',')).map(function (s) { return s.trim(); }).filter(Boolean);
const minAssignments = parseInt($env.RR_MIN_ASSIGNMENTS || '40', 10);
const minRatio = parseFloat($env.RR_MIN_SHARE_RATIO || '0.5');
const nowISO = new Date().toISOString();
const meta = $('Build Fairness Query').first().json;

if (pool.length < 2) {
  return [{ json: {
    kind: 'finding', class: 'config', severity: 'info', channel: 'post',
    dedupKey: 'watchdog::rr_unconfigured', count: 0, sample: [],
    detail: 'RR_POOL_OWNER_IDS holds fewer than two owner Ids, so the fairness check is off. Populate it with the round-robin pool you actually run.',
    emittedAt: nowISO, action: 'trigger', source: 'fairness',
  } }];
}

const raw = $input.first().json;
const status = raw.statusCode !== undefined ? raw.statusCode : 200;
const body = raw.body !== undefined ? raw.body : raw;

if (status !== 200) {
  const first = Array.isArray(body) && body[0] ? body[0] : {};
  return [{ json: {
    kind: 'finding', class: 'poll_health', severity: 'warning', channel: 'post',
    dedupKey: 'watchdog::fairness_query_failed', count: 0, sample: [],
    detail: (first.errorCode || 'HTTP_' + status) + ': ' + (first.message || 'fairness query failed'),
    emittedAt: nowISO, action: 'trigger', source: 'fairness',
  } }];
}

const counts = {};
for (const r of (body.records || [])) {
  const oid = (r.OwnerId || '').substring(0, 15);
  counts[oid] = (counts[oid] || 0) + Number(r.assignedCount || 0);
}

const poolCounts = pool.map(function (id) { return { ownerId: id, count: counts[id.substring(0, 15)] || 0 }; });
const total = poolCounts.reduce(function (a, b) { return a + b.count; }, 0);

if (total < minAssignments) {
  return [{ json: {
    kind: 'noop', reason: 'insufficient_data',
    detail: total + ' assignments across the pool in ' + meta.windowDays + ' days, below RR_MIN_ASSIGNMENTS=' + minAssignments + '. Share is not meaningful at this volume.',
    checkedAt: nowISO,
  } }];
}

const fairShare = total / pool.length;
const starved = poolCounts.filter(function (p) { return p.count > 0 && p.count < fairShare * minRatio; });
const zeroed = poolCounts.filter(function (p) { return p.count === 0; });
const out = [];

if (zeroed.length) {
  out.push({ json: {
    kind: 'finding', class: 'round_robin_zero', severity: 'error', channel: 'post',
    dedupKey: 'watchdog::rr_zero', count: zeroed.length,
    sample: zeroed.map(function (p) { return { id: p.ownerId, owner: p.ownerId, ageBizMinutes: null }; }),
    detail: zeroed.length + ' pool member(s) received zero assignments in ' + meta.windowDays + ' days against a pool total of ' + total + '. Check licence status, calendar connection, and pool membership before assuming the router is at fault.',
    emittedAt: nowISO, action: 'trigger', source: 'fairness',
  } });
}

if (starved.length) {
  out.push({ json: {
    kind: 'finding', class: 'round_robin_skew', severity: 'warning', channel: 'post',
    dedupKey: 'watchdog::rr_skew', count: starved.length,
    sample: starved.map(function (p) { return { id: p.ownerId, owner: p.ownerId + ' (' + p.count + ' vs ' + fairShare.toFixed(1) + ' fair share)', ageBizMinutes: null }; }),
    detail: starved.length + ' pool member(s) below ' + (minRatio * 100) + '% of the ' + fairShare.toFixed(1) + '-record equal share over ' + meta.windowDays + ' days (pool total ' + total + ').',
    emittedAt: nowISO, action: 'trigger', source: 'fairness',
  } });
}

if (out.length === 0) {
  out.push({ json: {
    kind: 'noop', reason: 'fairness_ok',
    detail: 'Pool of ' + pool.length + ' split ' + total + ' records with no member below ' + (minRatio * 100) + '% of equal share.',
    checkedAt: nowISO,
  } });
}

return out;
